68	    pub fn cost_for_tokens(
69	        &self,
70	        model_id: &str,
71	        input_tokens: u64,
72	        output_tokens: u64,
73	        cache_read_tokens: u64,
74	        cache_write_tokens: u64,
75	    ) -> f64 {
76	        let pricing = self.resolve(model_id);
77	        let input_cost = input_tokens as f64 * pricing.input_per_mtok / 1_000_000.0;
78	        let output_cost = output_tokens as f64 * pricing.output_per_mtok / 1_000_000.0;
79	        let cache_r = cache_read_tokens as f64 * pricing.cache_read_per_mtok / 1_000_000.0;
80	        let cache_w = cache_write_tokens as f64 * pricing.cache_write_per_mtok / 1_000_000.0;
81	        input_cost + output_cost + cache_r + cache_w
82	    }
83	
84	    pub fn resolve(&self, model_id: &str) -> &ModelPricing {
85	        if let Some(p) = self.models.get(model_id) {
86	            return p;
87	        }
88	        let normalized = normalize_model_id(model_id);
89	        if let Some(p) = self.models.get(&normalized) {
90	            return p;
91	        }
92	        for (key, pricing) in &self.models {
93	            if model_id.starts_with(key) || normalized.starts_with(key) {
94	                return pricing;
95	            }
96	        }
97	        tracing::warn!("unknown model '{}', using median pricing", model_id);
98	        self.median_pricing()
99	    }
100	
101	    fn median_pricing(&self) -> &ModelPricing {
102	        static MEDIAN: ModelPricing = ModelPricing {
103	            input_per_mtok: 3.0,
104	            output_per_mtok: 15.0,
105	            cache_read_per_mtok: 0.375,
106	            cache_write_per_mtok: 3.75,
107	        };
108	        &MEDIAN
109	    }
110	}
111	
112	fn normalize_model_id(id: &str) -> String {
113	    let id = id.trim();
114	    let id = id.split(':').last().unwrap_or(id);
115	    let parts: Vec<&str> = id.rsplitn(2, '-').collect();
116	    if parts.len() == 2 && parts[0].len() == 8 && parts[0].chars().all(|c| c.is_ascii_digit()) {
117	        parts[1].to_string()
118	    } else {
119	        id.to_string()
120	    }
121	}
