3	pub fn detect_pr_ref() -> Option<String> {
4	    if let Some(pr) = from_env() {
5	        return Some(pr);
6	    }
7	    if let Some(pr) = from_branch_name() {
8	        return Some(pr);
9	    }
10	    from_recent_commits()
11	}
12	
13	pub fn detect_feature_tag() -> Option<String> {
14	    let branch = git_branch_name()?;
15	    let prefix = branch.split('/').next()?;
16	    match prefix {
17	        "feat" | "feature" | "fix" | "bugfix" | "hotfix" | "chore" | "refactor" | "docs" | "test" | "ci" => {
18	            Some(prefix.to_string())
19	        }
20	        _ => None,
21	    }
22	}
23	
24	fn from_env() -> Option<String> {
25	    for var in &[
26	        "GH_PR_NUMBER",
27	        "GITHUB_PR_NUMBER",
28	        "PULL_REQUEST_NUMBER",
29	        "CI_MERGE_REQUEST_IID",
30	    ] {
31	        if let Ok(val) = std::env::var(var) {
32	            let val = val.trim().to_string();
33	            if !val.is_empty() {
34	                return Some(format!("#{}", val));
35	            }
36	        }
37	    }
38	    None
39	}
40	
41	fn from_branch_name() -> Option<String> {
42	    let branch = git_branch_name()?;
43	    let re = Regex::new(r"(?i)(?:^|/)([A-Z]+-\d+)").ok()?;
44	    re.captures(&branch).map(|c| c[1].to_uppercase())
45	}
46	
47	fn from_recent_commits() -> Option<String> {
48	    let output = std::process::Command::new("git")
49	        .args(["log", "--oneline", "-5", "--format=%s"])
50	        .output()
51	        .ok()?;
52	    if !output.status.success() {
53	        return None;
54	    }
55	    let stdout = String::from_utf8_lossy(&output.stdout);
56	    let re = Regex::new(r"\(#(\d+)\)").ok()?;
57	    for line in stdout.lines() {
58	        if let Some(caps) = re.captures(line) {
59	            return Some(format!("#{}", &caps[1]));
60	        }
61	    }
62	    None
63	}
64	
65	fn git_branch_name() -> Option<String> {
66	    let output = std::process::Command::new("git")
67	        .args(["rev-parse", "--abbrev-ref", "HEAD"])
68	        .output()
69	        .ok()?;
70	    if !output.status.success() {
71	        return None;
72	    }
73	    let branch = String::from_utf8_lossy(&output.stdout).trim().to_string();
74	    if branch.is_empty() || branch == "HEAD" {
75	        None
76	    } else {
77	        Some(branch)
78	    }
79	}
