6	#[derive(Debug, Clone, Serialize)]
7	pub struct CostRecord {
8	    pub id: Option<i64>,
9	    pub session_id: String,
10	    pub timestamp_ms: i64,
11	    pub model_id: String,
12	    pub input_tokens: u64,
13	    pub output_tokens: u64,
14	    pub cache_read_tokens: u64,
15	    pub cache_write_tokens: u64,
16	    pub cost_usd: f64,
17	    pub pr_ref: String,
18	    pub feature_tag: String,
