6	pub fn show(by: Option<&str>, pr: Option<&str>, json: bool, days: Option<i64>) -> Result<()> {
7	    let db_path = paths::data_dir().join("cost.db");
8	    if !db_path.exists() {
9	        if json {
10	            println!("{{}}");
11	        } else {
12	            println!("No cost data yet.");
13	            println!("Cost records are created when sessions are tracked with provenance.");
14	            println!("Run `codeflow cost record` to manually add cost data.");
15	        }
16	        return Ok(());
17	    }
18	
19	    let store = CostStore::open(&db_path)?;
20	    let project_dir = std::env::current_dir()
21	        .unwrap_or_default()
22	        .to_string_lossy()
23	        .to_string();
24	
25	    if let Some(pr_ref) = pr {
26	        return show_pr_detail(&store, pr_ref, json);
27	    }
28	
29	    if let Some(group) = by {
30	        return show_breakdown(&store, group, Some(&project_dir), days, json);
31	    }
32	
33	    show_summary(&store, Some(&project_dir), days, json)
34	}
