68	fn show_breakdown(store: &CostStore, group: &str, project_dir: Option<&str>, days: Option<i64>, json: bool) -> Result<()> {
69	    let groups = store.by_group(group, project_dir, days)?;
70	
71	    if json {
72	        println!("{}", serde_json::to_string_pretty(&groups)?);
73	        return Ok(());
74	    }
75	
76	    if groups.is_empty() {
77	        println!("No cost data for grouping by '{}'.", group);
78	        return Ok(());
79	    }
80	
81	    let header = match group {
82	        "pr" => "PR",
83	        "dev" | "developer" => "Developer",
84	        "model" => "Model",
85	        "day" => "Day",
86	        "session" => "Session",
87	        _ => group,
88	    };
89	
90	    println!();
91	    println!(
92	        "  {:<30} {:>10} {:>12} {:>12} {:>6}",
93	        header, "Cost ($)", "Input Tok", "Output Tok", "Count"
94	    );
95	    println!("  {}", "─".repeat(72));
96	
97	    for g in &groups {
98	        println!(
99	            "  {:<30} {:>10.2} {:>12} {:>12} {:>6}",
100	            truncate(&g.key, 30),
101	            g.cost_usd,
102	            format_number(g.input_tokens),
103	            format_number(g.output_tokens),
104	            g.record_count,
105	        );
106	    }
107	
108	    let total: f64 = groups.iter().map(|g| g.cost_usd).sum();
109	    println!("  {}", "─".repeat(72));
110	    println!("  {:<30} {:>10.2}", "TOTAL", total);
111	    println!();
112	
113	    Ok(())
114	}
