150	pub fn record_manual(
151	    session_id: &str,
152	    model_id: &str,
153	    input_tokens: u64,
154	    output_tokens: u64,
155	    cost_override: Option<f64>,
156	) -> Result<()> {
157	    let db_path = paths::data_dir().join("cost.db");
158	    std::fs::create_dir_all(paths::data_dir())?;
159	    let store = CostStore::open(&db_path)?;
160	
161	    let pricing = codeflow_core::pricing::PricingTable::bundled();
162	    let cost = cost_override.unwrap_or_else(|| {
163	        pricing.cost_for_tokens(model_id, input_tokens, output_tokens, 0, 0)
164	    });
165	
166	    let pr_ref = codeflow_core::pr_linker::detect_pr_ref().unwrap_or_default();
167	    let feature_tag = codeflow_core::pr_linker::detect_feature_tag().unwrap_or_default();
168	    let project_dir = std::env::current_dir()
169	        .unwrap_or_default()
170	        .to_string_lossy()
171	        .to_string();
172	
173	    let rec = codeflow_core::cost::CostRecord {
174	        id: None,
175	        session_id: session_id.to_string(),
176	        timestamp_ms: chrono::Utc::now().timestamp_millis(),
177	        model_id: model_id.to_string(),
178	        input_tokens,
179	        output_tokens,
180	        cache_read_tokens: 0,
181	        cache_write_tokens: 0,
182	        cost_usd: cost,
183	        pr_ref,
184	        feature_tag,
185	        project_dir,
186	        developer_id: whoami(),
187	    };
188	
189	    let id = store.record(&rec)?;
190	    println!(
191	        "✓ Cost recorded: ${:.4} ({} → {}) [id={}]",
192	        cost, model_id, format_number(input_tokens + output_tokens), id
193	    );
194	
195	    Ok(())
196	}
197	
198	fn whoami() -> String {
199	    std::env::var("USER")
200	        .or_else(|_| std::env::var("USERNAME"))
201	        .or_else(|_| std::env::var("LOGNAME"))
202	        .unwrap_or_else(|_| "unknown".to_string())
203	}
204	
205	fn format_number(n: u64) -> String {
206	    if n >= 1_000_000 {
207	        format!("{:.1}M", n as f64 / 1_000_000.0)
208	    } else if n >= 1_000 {
209	        format!("{:.1}K", n as f64 / 1_000.0)
210	    } else {
211	        n.to_string()
212	    }
213	}
214	
215	fn truncate(s: &str, max: usize) -> String {
216	    if s.chars().count() > max {
217	        let truncated: String = s.chars().take(max - 1).collect();
218	        format!("{}…", truncated)
219	    } else {
220	        s.to_string()
221	    }
222	}
