165	fn main() {
166	    tracing_subscriber::fmt()
167	        .with_env_filter(EnvFilter::from_default_env())
168	        .with_writer(std::io::stderr)
169	        .init();
170	
171	    let cli = Cli::parse();
172	
173	    let result = match cli.command {
174	        Commands::Init { global } => hooks::install(global),
175	        Commands::Uninit { global } => hooks::uninstall(global),
176	        Commands::Wrap { command } => wrap::execute(&command),
177	        Commands::Stats { json, days, waste } => stats::show(json, days, waste),
178	        Commands::Sync { once, api_url } => {
179	            let mut config = sync::SyncConfig { one_shot: once, ..Default::default() };
180	            if let Some(url) = api_url {
181	                config.api_url = url;
182	            }
183	            sync::run(config)
184	        }
185	        Commands::Login { auth_url } => auth::login(auth_url.as_deref()),
186	        Commands::Status => auth::status(),
187	        Commands::Logout => auth::logout(),
188	        Commands::Route { command, tokens, files } => handle_route(&command, tokens, &files),
189	
190	        Commands::Blame { file, json, session, trace } => {
191	            handle_blame(&file, json, session.as_deref(), trace)
192	        }
193	        Commands::Cost { by, pr, json, days, action } => {
194	            if let Some(act) = action {
195	                match act {
196	                    CostAction::Record { session, model, input_tokens, output_tokens, cost } => {
197	                        cost_cmd::record_manual(&session, &model, input_tokens, output_tokens, cost)
198	                    }
199	                }
200	            } else {
201	                cost_cmd::show(by.as_deref(), pr.as_deref(), json, days)
202	            }
203	        }
204	        Commands::Cache { action } => handle_cache(action),
205	        Commands::Hook { action } => handle_hook(action),
206	        Commands::Update => {
207	            println!("codeflow {}", env!("CARGO_PKG_VERSION"));
208	            println!("commit:  {}", option_env!("CODEFLOW_GIT_SHA").unwrap_or("dev"));
209	            println!("target:  {}", env!("TARGET"));
210	            println!();
211	            println!("Update: download latest from https://github.com/codeflow-dev/codeflow/releases");
212	            Ok(())
213	        }
214	    };
215	
216	    if let Err(e) = result {
217	        tracing::error!("{:#}", e);
218	        std::process::exit(1);
219	    }
220	}
