222	fn handle_blame(file: &str, json: bool, session: Option<&str>, trace: bool) -> anyhow::Result<()> {
223	    let db_path = paths::db_path();
224	    let store = codeflow_core::provenance::ProvenanceStore::open(&db_path)?;
225	
226	    let project_dir = std::env::current_dir().unwrap_or_default();
227	    let abs_path = if std::path::Path::new(file).is_absolute() {
228	        std::path::PathBuf::from(file)
229	    } else {
230	        project_dir.join(file)
231	    };
232	
233	    let rel_path = abs_path
234	        .strip_prefix(&project_dir)
235	        .map(|r| r.to_string_lossy().replace('\\', "/"))
236	        .unwrap_or_else(|_| file.to_string());
237	
238	    let mut records = store.query_by_file(&rel_path)?;
239	    if let Some(sid) = session {
240	        records.retain(|r| r.session_id == sid);
241	    }
242	
243	    if trace {
244	        println!("{}", codeflow_core::agent_trace::export_agent_trace(&records)?);
245	        return Ok(());
246	    }
247	
248	    if json {
249	        println!("{}", serde_json::to_string_pretty(&records)?);
250	        return Ok(());
251	    }
252	
253	    if records.is_empty() {
254	        println!("No provenance records for {}", rel_path);
255	        return Ok(());
256	    }
257	
258	    let file_content = std::fs::read_to_string(&abs_path).unwrap_or_default();
259	    let lines: Vec<&str> = file_content.lines().collect();
260	
261	    println!("Provenance: {} ({} records)\n", rel_path, records.len());
262	
263	    for rec in &records {
264	        let ts = chrono::DateTime::from_timestamp_millis(rec.timestamp_ms)
265	            .map(|dt| dt.format("%Y-%m-%d %H:%M").to_string())
266	            .unwrap_or_else(|| "?".to_string());
267	
268	        let ct_label = match rec.contributor_type {
269	            codeflow_core::provenance::ContributorType::Human => "\x1b[32mhuman\x1b[0m",
270	            codeflow_core::provenance::ContributorType::Ai => "\x1b[33mai\x1b[0m",
271	            codeflow_core::provenance::ContributorType::Mixed => "\x1b[36mmixed\x1b[0m",
272	            codeflow_core::provenance::ContributorType::Unknown => "\x1b[90munknown\x1b[0m",
273	        };
274	
275	        println!(
276	            "  {} | {} | {} | L{}-{} | {}",
277	            ts, ct_label, rec.model_id, rec.start_line, rec.end_line,
278	            &rec.code_hash[..rec.code_hash.len().min(12)]
279	        );
280	    }
281	
282	    if !lines.is_empty() {
283	        println!("\nLine attribution:");
284	        for (i, line) in lines.iter().enumerate() {
285	            let line_num = (i + 1) as u32;
286	            let attr = records.iter().find(|r| {
287	                r.start_line <= line_num && r.end_line >= line_num
288	            });
289	            let prefix = match attr {
290	                Some(r) => match r.contributor_type {
291	                    codeflow_core::provenance::ContributorType::Ai => "\x1b[33m AI \x1b[0m",
292	                    codeflow_core::provenance::ContributorType::Human => "\x1b[32m HU \x1b[0m",
293	                    codeflow_core::provenance::ContributorType::Mixed => "\x1b[36m MX \x1b[0m",
294	                    codeflow_core::provenance::ContributorType::Unknown => "\x1b[90m ?? \x1b[0m",
295	                },
296	                None => "\x1b[90m -- \x1b[0m",
297	            };
298	            println!("{:>4} |{}| {}", line_num, prefix, line);
299	        }
300	    }
301	
302	    Ok(())
