370	fn capture_provenance(
371	    session_id: &str,
372	    tool_name: &str,
373	    tool_input: &serde_json::Value,
374	) -> anyhow::Result<()> {
375	    let db_path = paths::db_path();
376	    let store = codeflow_core::provenance::ProvenanceStore::open(&db_path)?;
377	    let keypair = codeflow_core::attestation::load_or_generate()?;
378	    let project_dir = std::env::current_dir().unwrap_or_default();
379	
380	    // Step 1: diff against previous snapshots → record provenance for prior tool's changes
381	    let changes = codeflow_core::provenance::detect_changes(
382	        &project_dir,
383	        session_id,
384	        &store,
385	        &keypair,
386	    )?;
387	    for rec in &changes {
388	        store.record(rec)?;
389	        // Update snapshot to current state after recording
390	        if let Ok(hash) = codeflow_core::content_hash::hash_file(&project_dir.join(&rec.file_path)) {
391	            let mtime = codeflow_core::util::get_file_mtime_ns(
392	                project_dir.join(&rec.file_path).to_str().unwrap_or(""),
393	            )
394	            .unwrap_or(0);
395	            store.save_snapshot(session_id, &rec.file_path, &hash, mtime)?;
396	        }
397	    }
398	
399	    // Step 2: snapshot files targeted by the current tool for next comparison
400	    let files_to_snapshot = extract_target_files(tool_name, tool_input, &project_dir);
401	    if !files_to_snapshot.is_empty() {
402	        codeflow_core::provenance::snapshot_files(
403	            &project_dir,
404	            session_id,
405	            &store,
406	            &files_to_snapshot,
407	        )?;
408	    }
409	
410	    Ok(())
411	}
