413	fn extract_target_files(
414	    tool_name: &str,
415	    tool_input: &serde_json::Value,
416	    project_dir: &std::path::Path,
417	) -> Vec<String> {
418	    let mut files = Vec::new();
419	    match tool_name {
420	        "Edit" | "Write" | "MultiEdit" | "NotebookEdit" => {
421	            if let Some(fp) = tool_input.get("file_path").and_then(|v| v.as_str()) {
422	                if let Some(rel) = to_relative(fp, project_dir) {
423	                    files.push(rel);
424	                }
425	            }
426	        }
427	        "Bash" => {
428	            // Bash can modify files; we can't know which ones ahead of time.
429	            // Snapshot tracked files that git reports as modified after the command runs.
430	            // Since PreToolUse fires BEFORE execution, we can only snapshot what's
431	            // already tracked. The diff-on-next-PreToolUse pattern handles detection.
432	        }
433	        _ => {}
434	    }
435	    files
436	}
