445	fn handle_pre_tool_use() -> anyhow::Result<()> {
446	    let input = match read_stdin() {
447	        Ok(s) => s,
448	        Err(e) => {
449	            eprintln!("[codeflow] hook health-check: stdin read failed: {}", e);
450	            println!("{{}}");
451	            return Ok(());
452	        }
453	    };
454	
455	    let parsed: serde_json::Value = match serde_json::from_str(&input) {
456	        Ok(v) => v,
457	        Err(e) => {
458	            eprintln!(
459	                "[codeflow] hook health-check: invalid JSON from Claude Code: {}",
460	                e
461	            );
462	            println!("{{}}");
463	            return Ok(());
464	        }
465	    };
466	
467	    if !parsed.is_object() {
468	        eprintln!(
469	            "[codeflow] hook health-check: expected JSON object, got {}",
470	            parsed
471	        );
472	        println!("{{}}");
473	        return Ok(());
474	    }
475	
476	    let tool_name = match parsed.get("tool_name").and_then(|v| v.as_str()) {
477	        Some(name) => name,
478	        None => {
479	            println!("{{}}");
480	            return Ok(());
481	        }
482	    };
483	
484	    let tool_input = match parsed.get("tool_input") {
485	        Some(v) if v.is_object() => v,
486	        _ => {
487	            println!("{{}}");
488	            return Ok(());
489	        }
490	    };
491	
492	    // Log to session + dedup check (single connection, best-effort)
493	    let session_id = codeflow_core::util::session_id();
494	    let file_path = codeflow_core::session::extract_file_path(tool_name, tool_input);
495	    let session_log = open_session_log(&session_id).ok();
496	
497	    if let Some(ref sl) = session_log {
498	        let tool_input_str = serde_json::to_string(tool_input).unwrap_or_default();
499	        if let Ok(row_id) =
500	            sl.record_pre(tool_name, &tool_input_str, file_path.as_deref())
501	        {
502	            sl.write_pre_id(tool_name, file_path.as_deref(), row_id);
503	        }
504	    }
505	
506	    if std::env::var("CODEFLOW_PROVENANCE").as_deref() != Ok("0") {
507	        let _ = capture_provenance(&session_id, tool_name, tool_input);
508	    }
509	
510	    match tool_name {
511	        "Bash" => {
512	            if let Some(command) = tool_input.get("command").and_then(|c| c.as_str()) {
513	                if should_wrap(command) {
514	                    let codeflow_bin = std::env::current_exe()
515	                        .map(|p| p.to_string_lossy().to_string())
516	                        .unwrap_or_else(|_| "codeflow".to_string());
517	                    let quoted_bin = shell_quote(&codeflow_bin);
518	                    let rewritten = format!("{} wrap {}", quoted_bin, command);
519	                    let response = serde_json::json!({
520	                        "tool_input": {
521	                            "command": rewritten
522	                        }
523	                    });
524	                    println!("{}", serde_json::to_string(&response)?);
525	                    return Ok(());
526	                }
527	            }
528	            println!("{{}}");
529	        }
530	        "Read" | "Grep" | "Glob" => {
531	            if let Some(ref session_log) = session_log {
532	                let window_secs = std::env::var("CODEFLOW_DEDUP_WINDOW_SECS")
533	                    .ok()
534	                    .and_then(|v| v.parse().ok());
535	                let dedup =
536	                    codeflow_core::read_dedup::ReadDedup::new(session_log, window_secs);
537	                let tool_input_str = serde_json::to_string(tool_input).unwrap_or_default();
538	
539	                let result = match tool_name {
540	                    "Read" => {
541	                        if let Some(fp) = file_path.as_deref() {
542	                            dedup.check_read(fp)
543	                        } else {
544	                            codeflow_core::read_dedup::ReadDedupResult::Miss
545	                        }
546	                    }
547	                    "Grep" => dedup.check_grep(&tool_input_str),
548	                    "Glob" => dedup.check_glob(&tool_input_str),
549	                    _ => codeflow_core::read_dedup::ReadDedupResult::Miss,
550	                };
551	
552	                match result {
553	                    codeflow_core::read_dedup::ReadDedupResult::Hit {
554	                        context_message,
555	                        tokens_saved,
556	                    } => {
557	                        let response = serde_json::json!({
558	                            "additionalContext": context_message
559	                        });
560	                        println!("{}", serde_json::to_string(&response).unwrap_or_default());
561	
562	                        // Track savings
563	                        if tokens_saved > 0 {
564	                            if let Ok(tracking) =
565	                                codeflow_core::tracking::TrackingDb::open(&paths::db_path())
566	                            {
567	                                let _ = tracking.record(
568	                                    &codeflow_core::tracking::TrackingEvent {
569	                                        command: tool_name.to_string(),
570	                                        input_tokens: tokens_saved,
571	                                        output_tokens: 0,
572	                                        tokens_saved,
573	                                        layer:
574	                                            codeflow_core::tracking::SavingsLayer::ReadDedup,
575	                                        project: std::env::current_dir()
576	                                            .unwrap_or_default()
577	                                            .to_string_lossy()
578	                                            .to_string(),
579	                                        session_id: session_id.clone(),
580	                                    },
581	                                );
582	                            }
583	                        }
584	                        return Ok(());
585	                    }
586	                    codeflow_core::read_dedup::ReadDedupResult::Miss => {
587	                        println!("{{}}");
588	                    }
589	                }
590	            } else {
591	                println!("{{}}");
592	            }
593	        }
594	        _ => {
595	            println!("{{}}");
596	        }
597	    }
598	
599	    Ok(())
600	}
