602	fn handle_post_tool_use() -> anyhow::Result<()> {
603	    let input = match read_stdin() {
604	        Ok(s) => s,
605	        Err(_) => {
606	            println!("{{}}");
607	            return Ok(());
608	        }
609	    };
610	
611	    let parsed: serde_json::Value = serde_json::from_str(&input).unwrap_or_default();
612	    let tool_name = parsed.get("tool_name").and_then(|v| v.as_str());
613	    let tool_result = parsed
614	        .get("tool_result")
615	        .and_then(|v| v.as_str())
616	        .unwrap_or("");
617	
618	    if let Some(tn) = tool_name {
619	        if matches!(tn, "Read" | "Grep" | "Glob" | "Bash") {
620	            let file_path = parsed
621	                .get("tool_input")
622	                .and_then(|ti| codeflow_core::session::extract_file_path(tn, ti));
623	
624	            let session_id = codeflow_core::util::session_id();
625	            if let Ok(session_log) = open_session_log(&session_id) {
626	                if let Some(row_id) = session_log.take_pre_id(tn, file_path.as_deref()) {
627	                    let capped = if tool_result.len() > 1_048_576 {
628	                        &tool_result[..1_048_576]
629	                    } else {
630	                        tool_result
631	                    };
632	                    let content_hash =
633	                        blake3::hash(capped.as_bytes()).to_hex().to_string();
634	                    let token_count = codeflow_core::util::estimate_tokens(tool_result.len()) as i64;
635	
636	                    let mtime_ns =
637	                        file_path.as_deref().and_then(codeflow_core::util::get_file_mtime_ns);
638	
639	                    let _ = session_log.record_post(
640	                        row_id,
641	                        &content_hash,
642	                        token_count,
643	                        mtime_ns,
644	                    );
645	                }
646	            }
647	        }
648	    }
649	
650	    println!("{{}}");
651	    Ok(())
652	}
