665	fn should_wrap(command: &str) -> bool {
666	    let first_word = command.split_whitespace().next().unwrap_or("");
667	    let stem = std::path::Path::new(first_word)
668	        .file_stem()
669	        .and_then(|s| s.to_str())
670	        .unwrap_or(first_word);
671	    let wrappable = [
672	        "git", "npm", "npx", "pnpm", "yarn", "cargo", "pytest", "python",
673	        "tsc", "eslint", "ls", "find", "grep", "cat", "head", "tail",
674	        "docker", "kubectl", "go", "make", "pip", "ruff", "mypy", "vitest",
675	    ];
676	    wrappable.contains(&stem)
677	}
