679	fn shell_quote(s: &str) -> String {
680	    if s.contains(' ') || s.contains('\\') || s.contains('\'') || s.contains('"') {
681	        format!("'{}'", s.replace('\'', "'\\''"))
682	    } else {
683	        s.to_string()
684	    }
685	}
