55	        .or_else(|| std::env::var_os("USERPROFILE"))
56	        .map(PathBuf::from)
57	}
58	
59	fn dirs_next() -> PathBuf {
60	    std::env::var_os("LOCALAPPDATA")
61	        .map(PathBuf::from)
62	        .unwrap_or_else(|| {
63	            home_dir()
64	                .map(|h| h.join("AppData/Local"))
65	                .unwrap_or_else(|| PathBuf::from("/tmp"))
66	        })
67	}
